sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') return;

    var city  = g_form.getValue("city").trim().toLowerCase();
    var state = newValue.trim().toLowerCase();

    if (!city || !state) return;

    var baseValidator = new GlideAjax("BaseValidatorUtils");
    baseValidator.addParam("sysparm_name",  "checkDuplicateCityState");
    baseValidator.addParam("sysparm_city",  city);
    baseValidator.addParam("sysparm_state", state);

    baseValidator.getXMLAnswer(function(response) {
        if (response === 'true') {
            g_form.addErrorMessage("A base in this city and state already exists.");
            g_form.clearValue("city");
            g_form.clearValue("state");
        }
    });
}
